// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    Recorder rec;

    function setUp() public { 
        c = new airPort();
        rec = new Recorder();
    }

    // Fuzz parameters: from (caller account), value v, and one recipient tosAddr encoded into address
    // We keep _tos length = 1 to simplify observation (exactly one external call expected)
    function testFuzz_property(address from, uint256 v, address tosAddr) public {
        // keep addresses non-zero to be in admissible domain
        vm.assume(from != address(0));
        vm.assume(tosAddr != address(0));

        address[] memory tos = new address[](1);
        tos[0] = tosAddr;

        // The recorder exposes a function with the selector the reference uses (transferFrom)
        // and also one with the mutant selector (transfer). Both simply record the selector seen.
        // Call c.transfer(from, address(rec), tos, v) from any actor (use vm.prank to set msg.sender)
        vm.prank(from);
        bool ok;
        try c.transfer(from, address(rec), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: reference will invoke the callee using selector of transferFrom(...)
        // We observe what the recorder actually received: it stores the exact selector of the received call.
        // For the correct contract, the recorded selector must equal transferFrom selector.
        // The mutant changes the selector to transfer(...), so for some inputs the recorder will observe that different selector.

        bytes4 observed = rec.lastSelector();
        bytes4 expected = bytes4(keccak256("transferFrom(address,address,uint256)"));

        // Single assertion reading c-observable behavior (recorder is our deployed helper that observed c's external call).
        // The correct contract must always produce calls with the transferFrom selector, so observed == expected must hold.
        assertTrue(observed == expected);
    }
}

// Recorder: implements both possible target signatures so the ABI dispatch will call the exact function
contract Recorder {
    bytes4 public _lastSelector;

    // function matching transferFrom(address,address,uint256)
    function transferFrom(address a, address b, uint256 v) external {
        _lastSelector = msg.sig;
    }

    // function matching transfer(address,address,uint256)
    function transfer(address a, address b, uint256 v) external {
        _lastSelector = msg.sig;
    }

    function lastSelector() external view returns (bytes4) {
        return _lastSelector;
    }
}
